package com.yeyamo_mobile.api.culture_service.domain;
import static com.yeyamo_mobile.api.culture_service.domain.CultureEnums.*;import jakarta.persistence.*;import java.util.UUID;
@Entity @Table(name="language_exercises") public class LanguageExercise{@Id private UUID id;@Column(name="lesson_id",nullable=false)private UUID lessonId;@Column(name="item_id")private UUID itemId;@Enumerated(EnumType.STRING)@Column(nullable=false)private ExerciseType type;@Column(nullable=false,columnDefinition="TEXT")private String prompt;@Column(name="options_json",columnDefinition="TEXT")private String optionsJson;@Column(name="correct_answer",columnDefinition="TEXT")private String correctAnswer;@Column(name="display_order",nullable=false)private int displayOrder;protected LanguageExercise(){}public UUID getId(){return id;}public UUID getLessonId(){return lessonId;}public ExerciseType getType(){return type;}public String getPrompt(){return prompt;}public String getOptionsJson(){return optionsJson;}public int getDisplayOrder(){return displayOrder;}public boolean correct(String answer){return type==ExerciseType.PRONUNCIATION_SUBMISSION?false:correctAnswer!=null&&correctAnswer.equalsIgnoreCase(answer==null?"":answer.trim());}}
